def sections(text):
    """{heading: body} for the appendix, in document order."""
    if "\\appendix" not in text:
        raise SystemExit("no \\appendix in the document")
    body = text[text.index("\\appendix"):]
    end = body.find("\\end{document}")
    if end != -1:
        body = body[:end]
    parts, cur, buf = {}, "APPENDIX PREAMBLE", []
    n_sec, n_sub = 0, 0
    sec = None
    for line in body.split("\n"):
        m = re.match(r"\s*\\(sub)?section\{(.*?)\}", line)
        if m:
            parts[cur] = "\n".join(buf)
            if m.group(1):
                # counters are kept explicitly rather than derived from the keys already
                # collected: deriving them made an inserted subsection renumber every later
                # section, so the tool reported a wholesale rewrite where one block moved.
                n_sub += 1
                cur = f"{sec}.{n_sub}: {m.group(2)}"
            else:
                n_sec += 1
                n_sub = 0
                sec = chr(ord("A") + n_sec - 1)
                cur = f"{sec}: {m.group(2)}"
            buf = [line]
            continue
        buf.append(line)
    parts[cur] = "\n".join(buf)
    return parts


def digest(s):
    return hashlib.sha256(s.replace("\r\n", "\n").encode("utf-8")).hexdigest()


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    rev = args[0] if args else "HEAD"
    cur = sections(TEX.read_text(encoding="utf-8", errors="replace"))

    if "--list" in sys.argv:
        for k, v in cur.items():
            print(f"  {digest(v)}  {k}")
        return 0

    try:
        old_text = subprocess.run(["git", "show", f"{rev}:{REL}"], capture_output=True,
                                  check=True, cwd=HERE.parents[1]).stdout.decode(
            "utf-8", errors="replace")
    except subprocess.CalledProcessError:
        raise SystemExit(f"cannot read {REL} at {rev}")
    old = sections(old_text)

    added = [k for k in cur if k not in old]
    removed = [k for k in old if k not in cur]
    changed = [k for k in cur if k in old and digest(cur[k]) != digest(old[k])]

    print(f"appendix_identity vs {rev}: {len(cur)} sections, "
          f"{len(changed)} changed, {len(added)} added, {len(removed)} removed")
    print("CRLF normalized to LF before hashing.")
    unauthorized = []
    for tag, items in (("CHANGED", changed), ("ADDED", added), ("REMOVED", removed)):
        for k in items:
            want = "REMOVED" if tag == "REMOVED" else digest(cur[k])
            named = k in EXEMPT
            pinned = PINS.get(k)
            ok = named and pinned == want
            print(f"  {tag:8s} {'EXEMPT ' if ok else 'UNLISTED'} {k}")
            if ok:
                print(f"           basis: {EXEMPT[k]}")
            else:
                if not named:
                    print("           no EXEMPT entry: this change is not authorized")
                elif pinned is None:
                    print("           named in EXEMPT but NOT PINNED. That entry authorized an "
                          "earlier change; naming a section does not authorize its next edit.")
                else:
                    print(f"           PIN STALE: authorizes {pinned[:16]}, section is now "
                          f"{want[:16] if want != 'REMOVED' else want}")
                if want != "REMOVED":
                    print(f"           to authorize this state, add to PINS:  {k!r}: {want!r}")
                unauthorized.append((tag, k))
    if not (changed or added or removed):
        print("  appendix byte-identical to the revision")
    if unauthorized:
        print(f"\nFAIL -- {len(unauthorized)} unlisted appendix change(s)")
        return 1
    print("\nPASS -- every appendix change is listed with its basis")
    return 0


if __name__ == "__main__":
    sys.exit(main())
